    "explanation": "石膏之质原为硫养轻钙化合而成，其性凉而能散，有透表解肌之力，为清阳明胃腑实热之圣药，无论内伤、外感用之皆效，即他脏腑有实热者用之亦效。《神农本草经》原谓其微寒，其寒凉之力远逊于黄连、龙胆草、知母、黄柏等药，而其退热之功效则远过于诸药。《神农本草经》谓其微寒，则性非大寒可知。且谓其宜于产乳，其性尤纯良可知。\n　　盖言其性不甚寒凉，可用于产后也。乃后世注《神农本草经》者，不知产乳之乳字原作生字解，而竟谓石膏能治妇人无乳，支离殊甚。要知产后无外感之热，石膏原不可用。若确有外感实热，他凉药或在所忌，而独不忌石膏，以石膏之性非大寒，乃微寒也。是以汉季张仲景所着《金匮》中有竹皮大丸，治妇人乳中虚、烦乱、呕逆，中有石膏。夫乳中者，生子之时也，其烦乱呕逆必有外感之实热也，此实通《神农本草经》石膏主产乳之义以立方也。石膏医者多误认为大寒而用之，则宣散之性变为收敛(点豆腐者必用，取其能收敛也)，以治外感有实热者，竟将其痰火敛住，凝结不散，用至一两即足伤人，是变金丹为鸩毒也。迨至误用石膏偾事，流俗之见，不知其咎在不在石膏，转谓石膏用之其猛烈犹足伤人，而不者更可知矣。于是一倡百和，遂视用石膏为畏途，即有放胆用者，亦不过七八钱而止。夫石膏之质甚重，七八钱不过一大撮耳。以微寒之药，欲用一大撮扑灭寒温燎原之热，又何能有大效。是以愚用生石膏以治外感实热，轻证亦必至两许；若实热炽盛，又恒重用至四五两，或七八两，或单用，或与他药同用，必煎汤三四茶杯，分四五次徐徐温饮下，热退不必尽剂。如此多煎徐服者，欲以免病家之疑惧，且欲其药力常在上焦、中焦，而寒凉不至下侵致滑泻也。盖石膏生用以治外感实热，断无伤人之理，且放胆用之，亦断无不退热之理。惟热实脉虚者，其人必实热兼有虚热，仿白虎加人参汤之义，以人参佐石膏亦必能退热。盖诸药之退热，以寒胜热也，而石膏之退热，逐热外出也。是以将石膏煎服之后，能使内蕴之热息息自毛孔透出，且因其含有硫养轻，原具发表之性，以之煮汤又直如清水，服后其寒凉之力俱随发表之力外出，而毫无汁浆留中以伤脾胃，是以遇寒温之大热势若燎原，而放胆投以大剂白虎汤，莫不随手奏效。其邪实正虚者，投以白虎加人参汤，",
