    "explanation": "黄芪∶性温，味微甘。能补气，兼能升气，善治胸中大气(即宗气，为肺叶辟之原动力)下陷。《神农本草经》谓主大风者，以其与发表药同用，能祛外风，与养阴清热药同用，更能熄内风也。谓主痈疽、久败疮者，以其补益之力能生肌肉，其溃脓自排出也。表虚自汗者，可用之以固外表气虚。小便不利而肿胀者，可用之以利小便。妇女气虚下陷而崩带者，可用之以固崩带。为其补气之功最优，故推为补药之长，而名之曰也。\n　　【附案】沧州董氏女，年二十余。胸胁满闷，心中怔忡，动则自汗，其脉沉迟微弱，右部尤甚，为其脉迟，疑是心肺阳虚，询之不觉寒凉，知其为胸中大气下陷也。其家适有预购黄芪一包，俾用一两煎汤服之。其族兄××在座，其人颇知医学，疑药不对证。愚曰∶“勿多疑，倘有差错，余职其咎。”服后，果诸病皆愈。其族兄疑而问曰∶“《神农本草经》黄芪原主大风，有透表之力，生用则透表之力益大，与自汗证不宜，其性升而能补，有膨胀之力，与满闷证不宜，今单用生黄芪两许，而两证皆愈，并心中怔忡亦愈，其义何居？”答曰∶“黄芪诚有透表之力，气虚不能逐邪外出者，用于发表药中，即能得汗，若其阳强阴虚者，误用之则大汗如雨不可遏抑。惟胸中大气下陷，致外卫之气无所统摄而自汗者，投以黄芪则其效如神。至于证兼满闷而亦用之者，确知其为大气下陷，呼吸不利而作闷，非气郁而作闷也。至于心与肺同悬胸中，皆大气之所包举，大气升则心有所根据，故怔忡自止也。”继加桔梗二钱，知母三钱，又服两剂以善其后。\n　　一妇人产后四五日，大汗淋漓，数日不止，情势危急，气息奄奄，其脉微弱欲无，问其短气乎？心中怔忡且发热乎？病患不能言而颔之。知其大气下陷，不能吸摄卫气，而产后阴分暴虚，又不能维系阳分，故其汗若斯之脱出也。遂用生黄芪六钱，玄参一两，净萸肉、生杭芍各五钱，桔梗二钱，一剂汗减，至三剂诸病皆愈。从前五六日未大便，至此大便亦通下。\n　　邑王氏女，年二十余，心中寒凉，饮食减少，延医服药，年余无效，且益羸瘦。后愚诊视，其左脉微弱不起，断为肝虚证。其父知医，疑而问曰∶“向延医延医，皆言脾胃虚弱，相火衰损，故所用之方皆健脾养胃，补助相火，曾未有言及肝虚者，先生独言肝虚，但因左脉之微弱乎？抑",
