    "explanation": "山萸肉∶味酸性温。大能收敛元气，振作精神，固涩滑脱。因得木气最浓，收涩之中兼具条畅之性，故又通利九窍，流通血脉，治肝虚自汗，肝虚胁疼腰疼，肝虚内风萌动，且敛正气而不敛邪气，与他酸敛之药不同，是以《神农本草经》谓其逐寒湿痹也。其核与肉之性相反，用时务须将核去净，近阅医报有言核味涩，性亦主收敛，服之恒使小便不利，椎破尝之，果有有涩味者，其说或可信。\n　　山茱萸得木气最浓，酸收之中，大具开通之力，以木性喜条达故也。《神农本草经》谓主寒湿痹，诸家本草，多谓其能通利九窍，其性不但补肝，而兼能利通气血可知，若但视为收涩之品，则浅之乎视山茱萸矣。\n　　【附案】一人年四十余，外感痰喘，愚为治愈。但脉浮力微，按之即无。愚曰∶“脉象无根，当服峻补之剂，以防意外之变。”病家谓病患从来不受补药，服之则发狂疾，峻补之药，实不敢用。愚曰∶“既畏补药如是，备用亦可。”病家根据愚言。迟半日忽发喘逆，又似无气以息，汗出遍体，四肢逆冷，身躯后挺，危在顷刻。急用净萸肉四两，爆火煎一沸，即饮下，汗与喘皆微止。又添水再煎数沸饮下，病又见愈。复添水将原渣煎透饮下，遂汗止喘定，四肢之厥逆亦回。\n　　邻村李××，年二十余，素伤烟色，偶感风寒，医者用表散药数剂治愈。间日，忽遍身冷汗，心怔忡异常，自言气息将断，急求为调治。诊其脉浮弱无根，左右皆然。愚曰∶“此证虽危易治，得萸肉数两，可保无虞。”\n　　急取净萸肉四两，人参五钱。先用萸肉二两煎数沸，急服之，心定汗止，气亦接续，又将人参切作小块，用所余萸肉煎浓汤，送下病若失。\n　　一人年四十八，大汗淋漓，数日不止，衾褥皆湿，势近垂危，询方于愚。俾用净萸肉二两，煎汤饮之，汗遂止。翌晨，迎愚诊视，其脉沉迟细弱，而右部之沉细尤甚，虽无大汗，遍体犹湿。疑其胸中大气下陷，询之，果觉胸中气不上升，有类巨石相压，乃恍悟前次之大汗淋漓，实系大气陷后，卫气无所统摄而外泄也，遂用生黄一两，萸肉、知母各三钱，一剂胸次豁然，汗亦尽止，又服数剂以善其后。\n　　奉天友人田××妻，年五十余，素有心疼证，屡服理气活血之药，未能除根。一日反复甚剧，服药数剂，病未轻减。田××见既济汤后，载有张××所治心疼医案，心",
