    "brief": "清热凉血、养阴生津：热入营血、吐血衄血、阴虚发热、消渴。",
    "explanation": "鲜地黄∶性寒，微苦微甘。最善清热、凉血、化瘀血、生新血，治血热妄行、吐血、衄血、二便因热下血。其中含有铁质，故晒之、蒸之则黑，其生血、凉血之力，亦赖所含之铁质也。\n　　干地黄(即药局中生地黄)∶经日晒干，性凉而不寒，生血脉，益精髓，聪明耳目，治骨蒸劳热，肾虚生热。\n　　熟地黄(用鲜地黄和酒，屡次蒸晒而成)∶其性微温，甘而不苦，为滋阴补肾主药。治阴虚发热，阴虚不纳气作喘，劳瘵咳嗽，肾虚不能漉水，小便短少，积成水肿，以及各脏腑阴分虚损者，熟地黄皆能补之。\n　　【附案】邻村李媪，年七旬，劳喘甚剧，十年未尝卧寝。俾每日用熟地煎汤当茶饮之，数日即安卧，其家人反惧甚，以为如此改常，恐非吉兆，而不知其病之愈也。\n　　侯××之子，五岁，因服凉泻之药太过，致成慢惊，胃寒吐泻，常常螈，精神昏愦，目睛上泛，有危在顷刻之象。为处方，用熟地黄二两，生山药一两，干姜、附子、肉桂各二钱，净萸肉、野台参各三钱，煎汤一杯半，徐徐温饮下，吐泻螈皆止，精神亦振，似有烦躁之意，遂去干姜加生杭芍四钱，再服一剂全愈。\n　　一童子，年十四五，伤寒已过旬日，大便滑泻不止，心中怔忡异常，似有不能支持之状。脉至七至，按之不实。医者辞不治。投以熟地、生山药、生杭芍各一两，滑石八钱，甘草五钱，煎汤一大碗，徐徐温饮下，亦尽剂而愈。\n　　统观以上诸案，冯氏谓地黄大补肾中元气之说，非尽无凭。盖阴者阳之守，血者气之配，地黄大能滋阴养血，大剂服之，使阴血充足，人身元阳之气，自不至上脱下陷也。\n　　用熟地治寒温，恒为医家所訾。然遇其人真阴太亏，不能支持外感之热者，于治寒温药中，放胆加熟地以滋真阴，恒能挽回人命于顷刻。曾治一室女，资禀素羸弱，得温病五六日，痰喘甚剧。治以《金匮》小青龙汤加石膏，一剂喘顿止。时届晚八点钟，一夜安稳。至寅时喘复作，不若从前之剧，而精神恍惚，心中怔忡。再诊其脉，如水上浮麻不分至数，按之即无，此将脱之候也。取药不暇，幸有预购山药两许，急煎服之，病少愈。此际已疏方取药，方系熟地四两、生山药一两、野台参五钱。而近处药局无野台参，并他参亦鬻尽。再至他处，又恐误事。遂单煎熟地、山药饮之，病愈强半。一日之内，按其方连进三剂，",
