    "decoction": "研细冲服或入丸散，不入煎剂；不可久服过量。",
    "pattern": [
      "清心镇惊",
      "安神解毒",
      "心悸失眠",
      "惊风癫痫"
    ],
    "brief": "清心镇惊、安神解毒：心悸失眠、惊风癫痫、疮疡。",
    "explanation": "朱砂∶味微甘性凉，为汞五硫一化合而成。性凉体重，故能养精神、安魂魄、镇惊悸、熄肝风；为其色赤入心，能清心热，使不耗血，故能治心虚怔忡及不眠；能消除毒菌，故能治暴病传染、霍乱吐泻；能入肾导引肾气上达于心，则阴阳调和，水火既济，目得水火之精气以养其瞳子，故能明目；外用之，又能敷疮疡疥癞诸毒。\n　　邹润安曰∶凡药所以致生气于病中，化病气为生气也。凡用药取其禀赋之偏，以救人阴阳之偏胜也。是故药物之性，未有不偏者。徐洄溪曰∶药之用，或取其气，或取其味，或取其色，或取其形，或取其质，或取其性情，或取其所生之时，或取其所成之地。愚谓∶丹砂，则取其质与气与色为用者也。质之刚是阳，内含汞则阴气之寒是阴，色纯赤则阳，故其义为阳抱阴，阴承阳，禀自先天，不假作为。人之有生以前，两精相搏即有神，神根据于精乃有气，有气而后有生，有生而后知识具以成其魂，鉴别昭以成其魄，故凡精气失其所养，则魂魄遂不安，欲养之安之，则舍阴阳紧相抱持，密相承接之丹砂又奚取乎？然谓主身体五脏百病，养精神，安魂魄，益气明目何也？夫固以气寒，非温煦生生之具，故仅能于身体五脏百病中，养精神安魂魄益气明目耳。若身体五脏百病中，其不必养精神安魂魄益气明目者，则不必用丹砂也。血脉不通者，水中之火不继续也，烦满消渴者，火中之水失滋泽也，中恶腹痛阴阳不相保抱，邪得乘间以入，毒瓦斯疥诸疮，阳不畜阴而反灼阴，得惟药之阳抱阴，阴涵阳者治之，斯阳不为阴贼，阴不为阳累，诸疾均可已矣。按此为邹氏释《神农本草经》之文，可谓精细入微矣。\n　　【附案】壬寅秋月，霍乱流行。友人毛××之侄，受此证至垂危，衣冠既毕，舁之床上。毛××见其仍有微息，遂研朱砂钱许，和童便灌之，其病由此竟愈。\n　　一女子得霍乱至垂危，医者辞不治，时愚充教员于其处，求为延医，亦用药无效。适有摇铃卖药者，言能治此证，亦单重用朱砂钱许，治之而愈。愚从此知朱砂善化霍乱之毒菌。至己未在奉天拟得急救回生丹、卫生防疫宝丹两方，皆重用朱砂，治愈斯岁之患霍乱者不胜纪，传之他省亦救人甚伙，可征朱砂之功效神奇矣。然须用天产朱砂方效，若人工所造朱砂(色紫成大块作锭形者，为人工所造朱砂)，止可作颜料用，不堪入药",
