    "brief": "重镇安神、潜阳补阴、软坚散结、收敛固涩：眩晕、瘰疬、自汗、遗精、崩漏。",
    "explanation": "牡蛎∶味咸而涩，性微凉。能软坚化痰，善消瘰，止呃逆，固精气，治女子崩带。《神农本草经》谓其主温疟者，因温疟但在足少阳，故不与太阳相并为寒，但与阳明相并为热。牡蛎能入其经而祛其外来之邪。主惊恚怒气者，因惊则由于胆，怒则由于肝，牡蛎咸寒属水，以水滋木，则肝胆自得其养。且其性善收敛有保合之力，则胆得其助而惊恐自除，其质类金石有镇安之力，则肝得其平而恚怒自息矣。至于筋原属肝，肝不病而筋之或拘或缓者自愈，故《神农本草经》又谓其除拘缓也。\n　　牡蛎所消之瘰，即《神农本草经》所谓。而其所以能消者，非因其咸能软坚也。盖牡蛎之原质，为炭酸钙化合而成，其中含有沃度(亦名海典)，沃度者善消瘤赘瘰之药也(医方篇消瘰丸下附有验案可参观)。\n　　龙骨、牡蛎，若专取其收涩可以用。若用以滋阴，用以敛火，或取其收敛，兼取其开通者(二药皆敛而能开)，皆不可。\n　　若作丸散，亦可用，因之则其质稍软，与脾胃相宜也。然宜存性，不可过，若入汤剂仍以不为佳。\n　　今用者一概之，殊非所宜。\n　　",
