    "brief": "平肝潜阳、清肝明目：头痛眩晕、目赤翳障、视物昏花。",
    "explanation": "石决明∶味微咸，性微凉。为凉肝镇肝之要药。肝开窍于目，是以其性善明目，研细水飞作敷药，能除目外障，作丸散内服，熊消目内障(消内障丸散优于汤剂)。为其能凉肝，兼能镇肝，故善治脑中充血作疼作眩晕，因此证多系肝气肝火挟血上冲也。是以愚治脑充血证，恒重用之至两许。其性又善利小便，通五淋，盖肝主疏泄为肾行气，用决明以凉之镇之，俾肝气肝火不妄动自能下行，肾气不失疏泄之常，则小便之难者自利，五淋之涩者自通矣。此物乃鳆甲也，状如蛤，单片附石而生，其边有孔如豌豆，七孔九孔者佳，宜生研作粉用之，不\n　　宜用。\n　　",
