    "brief": "活血行气、祛风止痛：月经不调、痛经、头痛、胸胁疼痛。",
    "explanation": "芎∶味辛、微苦、微甘，气香窜，性温。温窜相并，其力上升、下降、外达、内透无所不至。故诸家本草，多谓其能走泄真气，然无论何药，皆有益有弊，亦视用之何如耳。其特长在能引人身清轻之气上至于脑，治脑为风袭头疼、脑为浮热上冲头疼、脑部充血头疼。其温窜之力，又能通活气血，治周身拘挛，女子月闭无子。虽系走窜之品，为其味微甘且含有津液，用之佐使得宜，亦能生血。\n　　四物汤中用芎，所以行地黄之滞也，所以治清阳下陷时作寒热也。若其人阴虚火升，头上时汗出者，芎即不宜用。\n　　【附案】友人郭××妻，产后头疼，或与一方当归、芎各一两煎服即愈。此盖产后血虚兼受风也。愚生平用芎治头疼不过二三钱。\n　　一人年三十余，头疼数年，服药或愈，仍然反复，其脉弦而有力，左关尤甚，知其肝血亏损肝火炽盛也。投以熟地、柏实各一两，生龙骨、生牡蛎、龙胆草、生杭芍、枸杞各四钱，甘草、芎各二钱，一剂疼止，又服数剂永不反复。\n　　又治一人，因脑为风袭头疼，用川芎、菊花各三钱，煎汤服之立愈。\n　　",
