    "decoction": "先煎去上沫，得汗即止；高血压、心脏病、甲亢、失眠者慎用。",
    "pattern": [
      "发汗解表",
      "宣肺平喘",
      "利水消肿",
      "风寒表实"
    ],
    "brief": "发汗解表、宣肺平喘、利水消肿：风寒表实、咳嗽气喘、水肿。",
    "explanation": "麻黄∶味微苦，性温。为发汗之主药。于全身之脏腑经络，莫不透达，而又以逐发太阳风寒为其主治之大纲。故《神农本草经》谓其主中风伤寒头痛诸证，又谓其主咳逆上气者，以其善搜肺风兼能泻肺定喘也。谓其破瘕积聚者，以其能透出皮肤毛孔之外，又能深入积痰凝血之中，而消坚化瘀之药可偕之以奏效也。且其性善利小便，不但走太阳之经，兼能入太阳之府，更能由太阳而及于少阴(是以伤寒少阴病用之)，并能治疮疽白硬，阴毒结而不消。\n　　太阳为周身之外廓，外廓者皮毛也，肺亦主之。风寒袭人，不但入太阳，必兼入手太阴肺经，恒有咳嗽微喘之证。麻黄兼入手太阴为逐寒搜风之要药，是以能发太阳之汗者，不仅麻黄，而《伤寒论》治太阳伤寒无汗，独用麻黄汤者，治足经而兼顾手经也。\n　　凡利小便之药，其中空者多兼能发汗，木通、蓄之类是也。发汗之药，其中空者多兼能利小便，麻黄、柴胡之类是也。伤寒太阳经病，恒兼入太阳之腑(膀胱)，致留连多日不解，麻黄治在经之邪，而在腑之邪亦兼能治之。盖在经之邪由汗而解，而在腑之邪亦可由小便而解，彼后世用他药以代麻黄者，于此义盖未之审也。\n　　受风水肿之证，《金匮》治以越婢汤，其方以麻黄为主，取其能祛风兼能利小便也。愚平素临证用其方服药后果能得汗，其小便即顿能利下，而肿亦遂消。特是，其方因麻黄与石膏并用，石膏之力原足以监制麻黄，恒有服之不得汗者，今变通其方，于服越婢汤之前，先用白糖水送服西药阿斯匹林一瓦半，必能出汗，趁其正出汗时，将越婢汤服下，其汗出必益多，小便亦遂通下。\n　　东人××博士，用麻黄十瓦，煎成水一百瓦，为一日之量，分三次服下，治慢性肾炎小便不利及肾脏萎缩小便不利，用之有效有不效，以其证之凉热虚实不同，不知用他药佐之以尽麻黄之长也。试观《金匮》水气门越婢汤，麻黄辅以石膏，因其脉浮有热也(脉浮故系有风实亦有热)，麻黄附子汤辅以附子，因其脉沉而寒也。通变化裁，息息与病机相符，是真善用麻黄者矣。\n　　古方中有麻黄，皆先将麻黄煮数沸吹去浮沫，然后纳他药，盖以其所浮之沫发性过烈，去之所以使其性归和平也。\n　　麻黄带节发汗之力稍弱，去节则发汗之力较强，今时用者大抵皆不去节，至其根则纯系止汗之品，本是一物",
