    "brief": "发汗解肌、温通经脉、助阳化气：风寒表虚、胸痹、心悸、经闭、水肿。",
    "explanation": "桂枝∶味辛微甘，性温。力善宣通，能升大气(即胸之宗气)，降逆气(如冲气肝气上冲之类)，散邪气(如外感风寒之类)。仲景苓桂术甘汤用之治短气，是取其能升也；桂枝加桂汤用之治奔豚，是取其能降也；麻黄、桂枝、大小青龙诸汤用之治外感，是取其能散也。而《神农本草经》论牡桂(即桂枝)，开端先言其主咳逆上气，似又以能降逆气为桂枝之特长，诸家本草鲜有言其能降逆气者，是用桂枝而弃其所长也。小青龙汤原桂枝、麻黄并用，至喘者去麻黄加杏仁而不去桂枝，诚以《神农本草经》原谓桂枝主吐吸\t(吐吸即喘)，去桂枝则不能定喘矣。乃医者皆知麻黄泻肺定喘，而鲜知桂枝降气定喘，是不读《神农本草经》之过也。桂枝善抑肝木之盛使不横恣，又善理肝木之郁使之条达也。为其味甘，故又善和脾胃，能使脾气之陷者上升，胃气之逆者下降，脾胃调和则留饮自除，积食自化。其宣通之力，又能导引三焦下通膀胱以利小便(小便因热不利者禁用，然亦有用凉药利小便而少加之作向导者)，惟上焦有热及恒患血证者忌用。\n　　桂枝非发汗之品，亦非止汗之品，其宣通表散之力，旋转于表里之间，能和营卫、暖肌肉、活血脉，俾风寒自解，麻痹自开，因其味辛而且甘，辛者能散，甘者能补，其功用在于半散半补之间也。故服桂枝汤欲得汗者，必啜热粥，其不能发汗可知；若阳强阴虚者，误服之则汗即脱出，其不能止汗可知。\n　　按∶《伤寒论》用桂枝，皆注明去皮，非去枝上之皮也。古人用桂枝，惟取当年新生嫩枝，折视之内外如一，皮骨不分，若见有皮骨可以辨者去之不用，故曰去皮，陈修园之侄鸣岐曾详论之。\n　　徐灵胎谓，受风有热者，误用桂枝则吐血，是诚确当之论。忆曾治一媪，年六旬，春初感冒风寒，投以发表之剂，中有桂枝数钱，服后即愈。其家人为其方灵，贴之壁上。至孟夏，复受感冒，自用其方取药服之，遂致吐血，经医治疗始愈。盖前所受者寒风，后所受者热风，故一则宜用桂枝，一则忌用桂枝，彼用桂枝汤以治温病者可不戒哉！特是，徐氏既知桂枝误用可致吐血，而其《洄溪医案》中载，治一妇人外感痰喘证，其人素有血证，时发时止，发则微嗽(据此数语断之，其血证当为咳血)，因痰喘甚剧，病急治标，投以小青龙汤而愈。\n　　用小青龙汤治外感痰喘，定",
