        "text": "燥湿化痰、降逆止呕、消痞散结：呕吐、痰多、胸脘痞闷、梅核气。凡味辛之至者，皆禀秋金收降之性，故力能下达为降胃安冲之主药。为其能降胃安冲，所以能止呕吐，能引肺中、胃中湿痰下行，纳气定喘。"
