    "explanation": "天花粉∶栝蒌根也，色白而亮者佳，味苦微酸，性凉而润。清火生津，为止渴要药(《伤寒论》小柴胡汤，渴者去半夏加栝蒌根，古方书治消渴亦多用之)。为其能生津止渴，故能润肺，化肺中燥痰，宁肺止嗽，治肺病结核。又善通行经络，解一切疮家热毒，疔痈初起者，与连翘、山甲并用即消，疮疡已溃者，与黄芪、甘草(皆须用生者)并用，更能生肌排脓，即溃烂至深旁串他处，不能敷药者，亦可自内生长肌肉，徐徐将脓排出(有案附载黄芪解下可参观)。大凡藤蔓之根，皆能通行经络，而花粉又性凉解毒，是以有种种功效也。\n　　",
