    "brief": "温中散寒、回阳通脉、温肺化饮：脘腹冷痛、呕吐、泄泻、寒饮咳喘。",
    "explanation": "干姜，味辛，性热。为补助上焦、中焦阳分之要药。为其味至辛，且具有宣通之力，与浓朴同用，治寒饮杜塞胃脘，饮食不化；与桂枝同用，治寒饮积于胸中，呼吸短气；与黄芪同用，治寒饮渍于肺中，肺痿咳嗽；与五味子同用，治感寒肺气不降，喘逆迫促；与赭石同用，治因寒胃气不降，吐血、衄血；与白术同用，治脾寒不能统血，二便下血，或脾胃虚寒，常作泄泻；与甘草同用，能调其辛辣之味，使不刺戟，而其温补之力转能悠长。《神农本草经》谓其逐风湿痹，指风湿痹之偏于寒者而言也，而《金匮》治热瘫痫，亦用干姜，风引汤中与石膏、寒水石并用者是也。此乃取其至辛之味，以开气血之凝滞也。有谓炮黑则性热，能助相火者，不知炮之则味苦，热力即减，且其气轻浮，转不能下达。\n　　徐灵胎曰∶“凡味浓之药主守，气浓之药主散，干姜气味俱浓，故散而能守。夫散不全散，守不全守，则旋转于经络脏腑之间，驱寒除湿、和血通气所必然矣，故性虽猛峻，不妨服食。”\n　　【附案】邻村高某年四十余，小便下血，久不愈。其脉微细而迟，身体虚弱恶寒，饮食减少。知其脾胃虚寒，中气下陷，黄坤载所谓血之亡于便溺者，太阴不升也。为疏方∶干姜、于术各四钱，生山药、熟地各六钱，乌附子、炙甘草各三钱，煎服一剂血见少，连服十余剂全愈。\n　　",
