    "decoction": "水煎温服或入丸散；苦寒败胃，不宜久服。",
    "pattern": [
      "清热燥湿",
      "泻火解毒",
      "湿热痞满",
      "呕吐"
    ],
    "brief": "清热燥湿、泻火解毒：湿热痞满、呕吐、泻痢、目赤、疮疡。",
    "explanation": "黄连∶味大苦，性寒而燥。为苦为火之味，燥为火之性，故善入心以清热，心中之热清，则上焦之热皆清，故善治脑膜生炎、脑部充血、时作眩晕、目疾肿疼、肉遮睛(目生云翳者忌用)，及半身以上赤游丹毒。其色纯黄，能入脾胃以除实热，使之进食(西人以黄连为健胃药，盖胃有热则恶心懒食，西人身体强壮且多肉食，胃有积热故宜黄连清之)，更由胃及肠，治肠下利脓血。为其性凉而燥，故治湿热郁于心下作痞满(仲景小陷胸汤，诸泻心汤皆用之)，女子阴中因湿热生炎溃烂。\n　　徐灵胎曰∶“苦属火性宜热此常理也。黄连至苦而反至寒，则得火之味与水之性，故能除水火相乱之病，水火相乱者湿热是也。是故热气目痛、伤、泪出、目不明，乃湿热在上者；肠、腹痛、下利，乃湿热在中者；妇人阴中肿痛，乃湿热在下者，悉能除之矣。凡药能去湿者必增热，能除热者必不能去湿，惟黄连能以苦燥湿，以寒除热，一举而两得焉。”\n　　黄连治目之功不必皆内服也。愚治目睛胀疼者，俾用黄连淬水，乘热屡用棉花瓤蘸擦眼上，至咽中觉苦乃止，则胀疼立见轻。又治目疾红肿作疼者，将黄芪连细末调以芝麻油，频频闻于鼻中，亦能立见效验。\n　　",
