    "brief": "清热泻火、生津止渴、除烦止呕：热病烦渴、胃热呕吐、肺热咳嗽。",
    "explanation": "苇与芦原系一物，其生于水边干地，小者为芦，生于水深之处，大者为苇。芦因生于干地，其色暗绿近黑，故字从卢(卢即黑色)，苇因生于水中，其形长大有伟然之意，故字从韦。《千金》苇茎汤∶薏苡仁、瓜瓣(即甜瓜瓣)各半升，桃仁五十枚，苇茎切二升，水二斗煮取五升，去渣纳前药三味，煮取二升，服一升，当有所见吐脓血。释者谓苇用茎不用根者，而愚则以为不然。根居于水底，是以其性凉而善升，患大头瘟者，愚常用之为引经要药(无苇根者，可代以荷叶)，是其上升之力可至脑部而况于肺乎？且其性凉能清肺热，中空能理肺气，而又味甘多液，更善滋阴养肺，则用根实胜于用茎明矣。\n　　今药局所鬻者名为芦根，实即苇根也。其善发痘疹者，以其有振发之性也；其善利小便者，以其体中空且生水中自能行水也；其善止吐血衄血者，以其性凉能治血热妄行，且血亦水属(血中明水居多)，其性能引水下行，自善引血下行也。其性颇近茅根，凡当用茅根而无鲜者，皆可以鲜芦根代之也。",
