    "brief": "敛肺涩肠、止痛：久咳、久泻、久痢、脱肛、遗精。",
    "explanation": "罂粟壳∶即罂粟花所结之子外包之壳也。其所结之子形如罂，中有子如粟，可作粥，甚香美(炒之则香)，故名其外皮为罂粟壳，药局间省文曰米壳。其味微酸，性平。其嫩时皮出白浆可制鸦片，以其犹含鸦片之余气，故其性能敛肺、涩肠、固肾，治久嗽、久痢、遗精、脱肛、女子崩带。嗽、痢初起及咳嗽兼外感者，忌用。\n　　罂粟壳，治久嗽、久痢，诚有效验，如虚劳咳嗽证，但用山药、地黄、枸杞、玄参诸药以滋阴养肺，其嗽不止者，加罂粟壳二三钱，则其嗽可立见轻减，或又少佐以通利之品，若牛蒡、射干诸药尤为稳妥。至于久痢，其肠中或有腐烂，若用三七、鸦胆子，化其腐烂，而其痢仍不止者，当将罂粟壳数钱，与山药、芍药诸药并用，连服数剂，其痢可全愈。\n　　",
