    "brief": "疏肝泄热、行气止痛、杀虫：胁痛、脘腹胀痛、疝气、虫积。",
    "explanation": "川楝子∶大如栗者是川楝子，他处楝子小而味苦，去核名金铃子。味微酸、微苦，性凉。酸者入肝，苦者善降，能引肝胆之热下行自小便出，故治肝气横恣，胆火炽盛，致胁下掀疼。并治胃脘气郁作疼，木能疏土也。\n　　其性虽凉，治疝气者恒以之为向导药，因其下行之力能引诸药至患处也。至他处之苦楝子，因其味苦有小毒，除虫者恒用之。\n　　",
