    "id": "df_61",
    "name": "薄荷（单味）",
    "alias": "薄荷单方",
    "herb": "薄荷",
    "source": "《医学衷中参西录·药物·薄荷解》",
    "six": "衷中",
    "school": "zhongzhong",
    "book": "zhongzhong",
    "kind": "danfang",
    "bencao": true,
