    "chapter": "药物",
    "composition": [
      {
        "herb": "薄荷",
        "prep": "",
        "text": "随证酌用（单味）"
      }
    ],
    "decoction": "后下，水煎温服；体虚多汗者慎用。",
    "pattern": [
      "疏散风热",
      "清利头目",
      "利咽透疹",
      "疏肝行气"
    ],
    "brief": "疏散风热、清利头目、利咽透疹、疏肝行气：风热感冒、头痛目赤、咽喉肿痛、麻疹。",
    "explanation": "薄荷∶味辛，气清郁香窜，性平，少用则凉，多用则热(如以鲜薄荷汁外擦皮肤少用殊觉清凉，多用即觉灼热)。其力能内透筋骨，外达肌表，宣通脏腑，贯串经络，服之能透发凉汗，为温病宜汗解者之要药。若少用之，亦善调和内伤，治肝气胆火郁结作疼，或肝风内动，忽然痫痉螈，头疼目疼，鼻渊鼻塞，齿疼咽喉肿疼，肢体拘挛作疼，一切风火郁热之疾，皆能治之。痢疾初起挟有外感者，亦宜用之，散外感之邪，即以清肠中之热，则其痢易愈。又善消毒菌(薄荷冰善消霍乱毒菌薄荷亦善消毒菌可知)，逐除恶气，一切霍乱痧证，亦为要药。为其味辛而凉，又善表疹瘾，愈皮肤瘙痒，为儿科常用之品。\n　　温病发汗用薄荷，犹伤寒发汗用麻黄也。麻黄服后出热汗，热汗能解寒，是以宜于伤寒；薄荷服后出凉汗，凉汗能清温，是以宜于温病。若以麻黄发温病之汗，薄荷发伤寒之汗，大抵皆不能出汗，即出汗亦必不能愈病也。\n　　薄荷古原名苛，以之作蔬，不以之作药，《神农本草经》、《名医别录》皆未载之，至唐时始列于药品，是以《伤寒论》诸方未有用薄荷者。然细审《伤寒论》之方，确有方中当用薄荷，因当时犹未列入药品，即当用薄荷之方，不得不转用他药者。试取伤寒之方论之，如麻杏甘石汤中之麻黄，宜用薄荷代之，盖麻杏甘石汤，原治汗出而喘无大热，既云无大热，其仍有热可知，有热而犹用麻黄者，取其泻肺定喘也。然麻黄能泻肺定喘，薄荷亦能泻肺定喘(薄荷之辛能抑肺气之盛，又善搜肺风)，用麻黄以热治热，何如用薄荷以凉治热乎？又如凡有葛根诸汤中之葛根，亦可以薄荷代之，盖葛根原所以发表阳明在经之热，葛根之凉不如薄荷，而其发表之力又远不如薄荷，则用葛根又何如用薄荷乎？斯非背古训也，古人当药物未备之时，所制之方原有不能尽善尽美之处，无他，时势限之也。吾人当药物既备之时，而不能随时化裁与古为新，是仍未会古人制方之意也。医界之研究伤寒者，尚其深思愚言哉。\n　　",
