        "text": "利水渗湿、健脾宁心：水肿、小便不利、痰饮、泄泻、心悸失眠。善理脾胃，因脾胃属土，土之味原淡(土味淡之理，徐灵胎曾详论之)，是以《内经》谓淡气归胃，而《慎柔五书》上述《内经》之旨，亦谓味淡能养脾阴。盖其性能化胃中痰饮为水液，引之输于脾而达于肺，复下循三焦水道以归膀胱，为渗湿利痰之主药。"
