        "text": "止血化瘀、通淋：吐血衄血、崩漏、尿血、心腹疼痛。善治气血不和、心腹疼痛、游风肿疼、颠仆血闷(用生蒲黄半两，煎汤灌下即醒)、痔疮出血(水送服一钱，日三次)、女子月闭腹痛、产后瘀血腹疼，为其有活血化瘀之力，故有种种诸效。若炒熟用之(不宜炒黑)，又善治吐血、咳血、衄血、二便下血、女子血崩带下。"
