    "decoction": "酒炒水煎，剂量从严；体虚者慎用。",
    "pattern": [
      "涌吐痰涎",
      "截疟",
      "疟疾",
      "痰饮。"
    ],
    "brief": "涌吐痰涎、截疟：疟疾、痰饮。",
    "explanation": "常山∶性凉，味微苦。善消脾中之痰，为治疟疾要药(疟疾皆系脾中多痰，凡久疟胁下有硬块名疟母者，皆系脾胀兼有痰也)。少服，则痰可徐消，若多服即可将脾中之痰吐出，为其多服即作呕吐，故诸家本草皆谓其有毒，医者用之治疟，亦因此不敢多用，遂至有效有不效。若欲用之必效，当效古人一剂三服之法，用常山五六钱，煎汤一大盅，分五六次徐徐温饮下，即可不作呕吐，疟疾亦有八九可愈。\n　　【附案】一九一七年，时当仲夏，愚因劳碌过度，兼受暑，遂至病疟。乃于不发疟之日清晨，用常山八钱，煎汤一大碗，徐徐温饮之，一次止饮一大口，饮至日夕而剂尽，心中分毫未觉难受，而疟亦遂愈。后遂变汤剂为丸剂，将常山轧细过罗，水泛为丸，桐子大，每服八分，一日之间自晨至暮服五次，共服药四钱，疟亦可愈。若病发时热甚剧者，可用生石膏一两煎汤，初两次服药时，可用此汤送服。西人谓病疟者有疟虫，西药金鸡纳霜，善除疟虫故善治疟，常山想亦善除疟虫之药品欤？\n　　",
