    "brief": "养心安神、润肠通便：心悸失眠、肠燥便秘。",
    "explanation": "柏子仁∶味微甘微辛，气香性平，多含油质。能补助心气，治心虚惊悸怔仲；能涵濡肝木，治肝气横恣胁疼；滋润肾水，治肾亏虚热上浮。虽含油质甚多，而性不湿腻，且气香味甘实能有益脾胃，《神农本草经》谓其除风湿痹，胃之气化壮旺，由中四达而痹者自开也。其味甘而兼辛，又得秋金肃降之气，能入肺宁嗽定喘，导引肺气下行。统言之，和平纯粹之品，于五脏皆有补益，故《神农本草经》谓安五脏也。宜去净皮，炒香用之，不宜去油。\n　　《神农本草经》谓柏实能安五脏，而实于肝脏尤宜也。曾治邻村毛姓少年，其肝脏素有伤损，左关脉独微弱，一日忽胁下作疼，俾单用柏子仁一两，煎汤服之立愈。观此，则柏子仁善于理肝可知矣。\n　　",
