    "brief": "补中益气、养血安神：脾虚食少、乏力、失眠、调和诸药。",
    "explanation": "大枣∶味甘微辛，性温。其津液浓浓滑润，最能滋养血脉、润泽肌肉、强健脾胃、固肠止泻、调和百药能缓猛药健悍之性，使不伤脾胃。是以十枣汤、葶苈大枣汤诸方用之。若与生姜并用，为调和营卫之妙品，是以桂枝汤、柴胡汤诸方用之。《内经》谓其能安中者，因其味至甘能守中也。又谓其能通九窍者，因其津液滑润且微有辛味，故兼有通利之能也。谓其补少气少津液者，为其味甘能益气，其津液浓浓滑润，又能补人身津液之不足也。虽为寻常食品，用之得当能建奇功。\n　　周伯度曰∶“生姜味辛色黄，由阳明入卫，大枣味甘色赤，由太阴入营。其能入营由于甘中有辛，惟其甘守之力多，得生姜乃不至过守；生姜辛通之力多，得大枣乃不至过通，二药并用所以为和营卫主剂。”\n　　《神农本草经》名之为大枣者，别于酸枣仁之小枣也。凡枣之酸者皆小，甘者皆大，而大枣又非一种，约以生食不脆、干食肉多、味极甘者为入药之品。若用为服食之物，而日日食之者，宜先用水将枣煮两三沸，迟一点钟将枣捞出(此时尝其煮枣之水甚苦，故先宜将苦水煮出)，再用饭甑上蒸熟，则其味甘美，其性和平，可以多服久服，不至生热。\n　　【附案】邑中友人赵××，身体素羸弱，年届五旬，饮食减少，日益消瘦，询方于愚，俾日食熟大枣数十枚，当点心用之。后年余觌面貌较前丰腴若干，自言∶“自闻方后，即日服大枣，至今未尝间断，饮食增于从前三分之一，是以身形较前强壮也。”\n　　表叔高××，年过五旬，胃阳不足，又兼肝气郁结，因之饮食减少，时觉满闷，服药半载，毫无效验。适愚远游还里，觌面谈及，俾用大枣六斤，生姜一斤，切片，同在饭甑蒸熟，臼内捣如泥，加桂枝尖细末三两，炒熟麦面斤半，和匀捏成小饼，炉上炙干，随意当点心服之，尽剂而愈。\n　　",
