    "brief": "补肾、温肺、润肠：腰膝酸软、虚寒喘咳、肠燥便秘。",
    "explanation": "胡桃(亦名核桃)∶味微甘，气香，性温。多含油质，将油榨出，须臾即变黑色。为滋补肝肾、强健筋骨之要药，故善治腰疼腿疼，一切筋骨疼痛。为其能补肾，故能固齿牙、乌须发，治虚劳喘嗽、气不归元、下焦虚寒、小便频数、女子崩带诸证。其性又能消坚开瘀，治心腹疼痛、砂淋、石淋、杜塞作疼、肾败不能漉水、小便不利。或误吞铜物，多食亦能消化(试与铜钱同嚼，其钱即碎，能化铜可知)。又善消疮疽及皮肤疥癣头上白秃，又能治疮毒深入骨髓，软弱不能步履。\n　　【附案】一幼童，五龄犹不能行，身多疮疡，治愈复发，知其父素有梅毒，此系遗传性病在骨髓也。为疏方，每剂中用胡桃仁八钱，佐以金银花、白鲜皮、土茯苓、川贝母、玄参、甘草诸药，如此方少有加减，服药二十余剂，其疮皆愈，从此渐亦能行步矣。\n　　附∶古方治虚寒喘嗽、腰腿酸痛，用胡桃仁二十两烂研，补骨脂十两酒蒸为末，密调如饴，每晨酒服一大匙，不能饮者热水调服。汪庵谓，补骨脂属火，入心包命门能补相火以通君火、暖丹田、壮元阳；胡桃属木，能通命门、利三焦、温肺润肠、补养气血，有木火相生之妙。愚常用之以治下焦虚寒之证，诚有奇效。上方加杜仲一斤，生姜炒蒜四两，同为丸，名青娥丸。治肾虚腰疼，而此方不但治肾虚腰疼也，以治虚寒腿疼亦极效验。曾治一媪年过六旬，腿疼年余不愈，其脉两尺沉细，俾日服青娥丸月余全愈。若虚寒之甚者，可于方中加生硫黄三两。\n　　",
