    "brief": "收敛固涩、益气生津、补肾宁心：久咳虚喘、自汗盗汗、遗精、久泻、心悸失眠。",
    "explanation": "五味子∶性温，五味俱备，酸、咸居多。其酸也能敛肺，故《神农本草经》谓主咳逆上气；其咸也能滋肾，故《神农本草经》谓其强阴益男子精。其酸收之力，又能固摄下焦气化，治五更泄泻、梦遗失精，及消渴小便频数，或饮一溲一，或饮一溲二。其至酸之味，又善入肝，肝开窍于目，故五味子能敛瞳子散大。然其酸收之力甚大，若咳逆上气挟有外感者，须与辛散之药同用(若干姜、生姜、麻黄、细辛诸药)，方能服后不至留邪。凡入煎剂宜捣碎，以其仁之味辛与皮之酸味相济，自不至酸敛过甚，服之作胀满也。\n　　邹润安曰∶“《伤寒论》中，凡遇咳者，总加五味子、干姜，义甚深奥，经云‘脾气散精，上归于肺，’是故咳虽肺病，而其源实主于脾，惟脾家所散上归之精不清，则肺家通调水道之令不肃，后人治咳但知润肺消痰，不知润肺则肺愈不清，消痰则转能伤脾，而痰之留于肺者究莫消也。干姜温脾肺，是治咳之来路，来路清则咳之源绝矣；五味使肺气下归于肾，是治咳之去路，去路清则气肃降矣。合两药而言，则为一开一阖，当开而阖是为关门逐盗；当阖而开则恐津液消亡，故小青龙汤及小柴胡汤、真武汤、四逆散之兼咳者皆用之，不嫌其表里无别也。”\n　　",
