    "brief": "利湿浊、祛风湿：膏淋、白浊、带下、风湿痹痛。",
    "explanation": "萆∶味淡，性温。为其味淡而温，故能直趋膀胱温补下焦气化，治小儿夜睡遗尿，或大人小便频数，致大便干燥。其温补之性，兼能涩精秘气，患淋证者禁用，醒脾升陷汤后曾详论之。萆为治失溺要药不可用之治淋。《名医别录》谓萆治阴萎、失溺、老人五缓。盖失溺之证实因膀胱之括约筋少约束之力，此系筋缓之病，实为五缓之一，萆善治五缓，所以治之。拙拟醒脾升陷汤中，曾重用萆以治小便频数不禁，屡次奏效，是萆为治失溺之要药可知矣。乃萆厘清饮竟用之以治膏淋，何其背谬若是？愚在籍时，邻村有病淋者，医者投以萆厘清饮，两剂，其人小便滴沥不通。再服各种利小便药，皆无效。后延愚延医，已至十日，精神昏愦，毫无知觉，脉数近十至，按之即无，因谓其家人曰∶“据此脉论，即小便通下，亦恐不救。”其家人恳求甚切，遂投以大滋真阴之剂，以利水之药佐之。灌下移时，小便即通，床褥皆湿。再诊其脉，微细欲无，愚急辞归。后闻其人当日即亡。近又在津治一淋证，服药十剂已愈，隔两月病又反复，时值愚回籍，遂延他医治疗，方中亦重用萆。服两剂，小便亦滴沥不通，服利小便药亦无效。遂屡用西法引溺管兼服利小便之药，治近一旬，小便少通滴沥，每小便一次，必须两小时。继又服滋阴利水之药十剂始全愈。\n　　",
