    "explanation": "鸡内金∶鸡之脾胃也，其中原含有稀盐酸，故其味酸而性微温，中有瓷、石、铜、铁皆能消化，其善化瘀积可知。《内经》谓“诸湿肿满，皆属于脾”，盖脾中多回血管，原为通彻玲珑之体，是以居于中焦以升降气化，若有瘀积，气化不能升降，是以易致胀满。用鸡内金为脏器疗法，若再与白术等分并用，为消化瘀积之要药，更为健补脾胃之妙品，脾胃健壮，益能运化药力以消积也。且为鸡内金含有稀盐酸，不但能消脾胃之积，无论脏腑何处有积，鸡内金皆能消之，是以男子癖、女之瘕，久久服之皆能治愈。又凡虚劳之证，其经络多瘀滞，加鸡内金于滋补药中，以化其经络之瘀滞而病始可愈。至以治室女月信一次未见者，尤为要药，盖以其能助归、芍以通经，又能助健补脾胃之药，多进饮食以生血也。\n　　女子干血劳之证，最为难治之证也，是以愈者恒少。惟善用鸡内金者，则治之多能奏效。愚向为妇女治病，其廉于饮食者，恒白术与鸡内金并用。乃有两次遇有此药者，一月间月信来三次，恍悟此过用鸡内金之弊也。\n　　盖鸡内金善化瘀血，即能催月信速于下行也。然月信通者服之，或至过通，而月信之不通者服之，即不难下通。况《内经》谓“中焦受气取汁，变化而赤，是为血。”血之来源，原在脾胃能多消饮食。鸡内金与白术并用，原能健脾胃以消饮食也。况脾为后天资生之本，居中央以灌溉四旁。此证之多发劳嗽者，脾虚肺亦虚也，多兼灼热者，脾虚而肾亦虚也。再加山药、地黄、枸杞诸药以补肺滋肾，有鸡内金以运化之，自能变其浓浓之汁浆为精液，以灌注于肺肾也。迨至服药日久，脏腑诸病皆愈，身体已渐撤消，而月信仍不至者，不妨再加虫、水蛭诸药。如嫌诸药之猛悍，若桃仁、红花亦可以替代。然又须多用补正之药品以驾驭之，始能有益而无害也。愚向曾本此意拟一方，名资生通脉汤，后列用其方治愈之案数则，可参观也。\n　　《内经》谓“女子二七天癸至”，所谓二七者，十四岁也。然必足年足月十四岁，是则室女月信之通，当在年十五矣。若是年至十五月信不通，即当预为之防。宜用整条生怀山药，轧细过罗，每用一两或八钱，煮作茶汤，调以蔗糖令适口，以之送服生鸡内金细末五分许，当点心用之。日两次，久则月信自然通下。此因山药善养血，鸡内金善通血也。若至因月信不",
