    "explanation": "穿山甲∶味淡，性平。气腥而窜，其走窜之性无微不至，故能宣通脏腑、贯彻经络、透达关窍，凡血凝、血聚为病皆能开之。以治疔痈，放胆用之，立见功效。并能治瘕积聚、周身麻痹、二便闭塞、心腹疼痛。若但知其长于治疮，而忘其他长，犹浅之乎视山甲也。\n　　疔痈初起未成脓者，愚恒用山甲、皂刺各四钱，花粉、知母各六钱，乳香、没药各三钱，全蜈蚣三条，服之立消。以治横(鱼口便毒之类)亦极效验。其已有脓而红肿者，服之红肿即消，脓亦易出。至瘕积聚、疼痛麻痹、二便闭塞诸证，用药治不效者，皆可加山甲作向导。友人黄××谓，身上若有血箭证，或金伤出血不止者，敷以山甲末立止，屡次用之皆效，蛤粉炒透用，惟以之熬膏药用生者。\n　　",
