    "decoction": "去头足，研末或水煎，剂量从严；孕妇禁用。",
    "pattern": [
      "息风镇痉",
      "通络止痛",
      "攻毒散结",
      "抽搐"
    ],
    "brief": "息风镇痉、通络止痛、攻毒散结：抽搐、中风口眼歪斜、疮疡、头痛。",
    "explanation": "蜈蚣∶味微辛，性微温。走窜之力最速，内而脏腑，外而经络，凡气血凝聚之处皆能开之。性有微毒，而转善解毒，凡一切疮疡诸毒皆能消之。其性尤善搜风，内治肝风萌动、癫痫眩晕、抽掣螈、小儿脐风；外治经络中风、口眼歪斜、手足麻木。为其性能制蛇，故又治蛇症及蛇咬中毒。外敷治疮甲(俗名鸡眼为末敷之以生南星末醋调、敷四周)，用时宜带头足，去之则力减，且其性原无大毒，故不妨全用也。\n　　【附案】奉天陈××之幼子，年五岁，周身壮热，四肢拘挛，有抽掣之状，渴嗜饮水，大便干燥，知系外感之热，引动其肝经风火上冲脑部，致脑气筋妄行，失其主宰之常也。投以白虎汤，方中生石膏用一两，又加薄荷叶一钱，钩藤钩二钱，全蜈蚣二条，煎汤一盅，分两次温饮下，一剂而抽掣止、拘挛舒，遂去蜈蚣，又服一剂热亦退净。\n　　奉天那姓幼子，生月余，周身壮热抽掣，两日之间不食乳、不啼哭，奄奄一息，待时而已。来院求治。知与前证仿佛，为其系婴孩，拟用前方将白虎汤减半，为其抽掣甚剧，薄荷叶、钩藤钩、蜈蚣其数仍旧，又加全蝎三个，煎药一盅，不分次数徐徐温灌之，历十二小时，药灌已而抽掣愈，食乳知啼哭矣。翌日，又为疏散风清热镇肝之药，一剂全愈。隔两日其同族又有三岁幼童，其病状与陈姓子相似，即治以陈姓子所服药，一剂而愈。\n　　奉天吴姓男孩，生逾百日，周身壮热，时作抽掣，然不甚剧，投以白虎汤，生石膏用六钱，又加薄荷叶一钱，蜈蚣一条，煎汤分三次灌下，尽剂而愈。此四证皆在暮春上旬，相隔数日之间，亦一时外感之气化有以使之然也。\n　　一人年三十余，陡然口眼歪斜，受病之边目不能瞬，用全蜈蚣二条为末，以防风五钱煎汤送服，三剂全愈。\n　　有病噎膈者，服药无效，偶思饮酒，饮尽一壶而病愈。后视壶中有大蜈蚣一条，恍悟其病愈之由，不在酒实在酒中有蜈蚣也。盖噎膈之证，多因血瘀上脘，为有形之阻隔(西人名胃癌，谓其处凸起如山石之有岩也)，蜈蚣善于开瘀，是以能愈。观于此，则治噎膈者，蜈蚣当为急需之品矣。为其事甚奇，故附记于此。\n　　",
