    "explanation": "蝉蜕∶无气味，性微凉。能发汗，善解外感风热，为温病初得之要药。又善托隐疹外出，有皮以达皮之力，故又为治隐疹要药。与蛇蜕并用，善治周身癞癣瘙痒。若为末单服，又善治疮中生蛆，连服数次其蛆自化。为其不饮食而时有小便，故又善利小便；为其为蝉之蜕，故又能脱目翳也。\n　　蝉亦止小儿夜啼，又善医音哑。忆一九三六年秋，余友姚××，偶为外感所袭，音哑月余，余为拟方，用净蝉蜕(去足土)二钱，滑石一两，麦冬四钱，胖大海五个，桑叶、薄荷叶各二钱，嘱其用水壶泡之代茶饮，一日音响，二日音清，三日全愈。以后又用此方治愈多人，屡试屡验。\n　　受业孙××谨识",
