    "id": "df_85",
    "name": "羚羊角（单味）",
    "alias": "羚羊角单方",
    "herb": "羚羊角",
    "source": "《医学衷中参西录·药物·羚羊角解》",
    "six": "衷中",
    "school": "zhongzhong",
