    "decoction": "另煎兑服或研末冲服；孕妇慎用。",
    "pattern": [
      "平肝息风",
      "清肝明目",
      "散血解毒",
      "高热惊痫"
    ],
    "brief": "平肝息风、清肝明目、散血解毒：高热惊痫、抽搐、目赤、温病发斑。",
    "explanation": "羚羊角∶性近于平不过微凉。最能清大热，兼能解热中之大毒。且既善清里，又善透表，能引脏腑间之热毒达于肌肤而外出，疹之未出，或已出而速回者，皆可以此表之，为托表麻疹之妙药。即表之不出而毒瓦斯内陷者，服之亦可内消。又善入肝经以治肝火炽盛，至生眼疾，及患吐衄者之妙药。所最异者性善退热却不甚凉，虽过用之不致令人寒胃作泄泻，与他凉药不同。此乃具有特殊之良能，非可以寻常药饵之凉热相权衡也。或单用之，或杂他药中用，均有显效。今特将所用羚羊角治愈之病十余则，详录于下以征明之。\n　　【附案】壬寅之岁，季春夜半，表弟刘××之子，年六岁，于数日间出疹，因其苦于服药，强与之即作呕吐，所以未求诊视。今夜忽大喘不止，有危在顷刻之势，不知还可救否。遂与同往视之，见其不但喘息迫促，且精神恍惚，肢体骚扰不安；脉象摇摇而动，按之无根；其疹出第三日即靥，微有紫痕，知其毒火内攻，肝风已动也。因思熄风、清火，且托毒外出，惟羚羊角一味能兼擅其长，且色味俱无，煎汤直如清水，孺子亦不苦服。遂急取羚羊角三钱煎汤，视其服下，过十余分钟即安然矣。\n　　奉天王××之孙女，年五六岁，患眼疾。先经东医治数日不愈，延为诊视。其两目肉长满，遮掩目睛，分毫不露，且疼痛异常，号泣不止。遂单用羚羊角二钱，俾急煎汤服之。时已届晚九点钟，至夜半已安然睡去，翌晨肉已退其半。又煎渣服之，全愈。盖肝开窍于目，羚羊角性原属木，与肝有同气相求之妙，故善入肝经以泻其邪热，且善伏肝胆中寄生之相火，为眼疾有热者无上妙药。\n　　奉天韩姓媪，年六十余，臂上生疔毒，外科不善治疗，致令毒火内攻，热痰上壅，填塞胸臆，昏不知人。\n　　有东医数人为治移时不愈，气息益微。延为诊视，知系痰厥。急用蓬砂五钱，煮至融化，灌下三分之二，须臾呕出痰涎若干，豁然顿醒。而患处仍肿疼，其疔生于左臂，且左脉较右脉洪紧，知系肝火炽盛，发为肿毒也。遂投以清火解毒之剂，又单将羚羊角二钱煎汤兑服，一剂而愈。\n　　奉天王××之幼女，年五岁，因出疹倒靥过急，毒火内郁，已过旬日，犹大热不止，其形体病久似弱，而脉象确有实热，且其大便干燥，小便黄赤，知非轻剂所能治愈。将为疏方，为开羚羊角二钱，生石膏二两，煎汤一",
