    "brief": "收敛止血、化瘀、利尿：吐血、衄血、尿血、崩漏、小便不利。",
    "explanation": "血余者，发也，不则其质不化，故必为炭然后入药。其性能化瘀血、生新血有似三七，故善治吐血、衄血。而常服之又可治劳瘵，因劳瘵之人，其血必虚而且瘀，故《金匮》谓之血痹虚劳。人之发，原人心血所生，服之能自还原化，有以人补人之妙，则血可不虚，而其化瘀之力，又善治血痹，是以久久服之，自能奏效。\n　　其性又能利小便(《金匮》利小便之方，有膏发煎)，以人之小便半从血管渗出，血余能化瘀血生新血，使血管流通故有斯效。其化瘀生新之力，又善治大便下血腥臭，肠中腐烂，及女子月信闭塞，不以时至。\n　　制血余炭法∶用壮年剃下之发，碱水洗净，再用清水淘去碱味，晒干用铁锅炮至发质皆化为膏，晾冷，轧细，过罗，其发质未尽化者，可再炮之。\n　　",
