        "text": "止血、利尿、明目、催生：鼻衄、尿血、目翳、难产。内服能催生下胎衣，鼻嗅之能止衄血，点眼上能消目翳。三、医论1．六经总论属性：伤寒治法以六经分篇，然手足各有六经，实则十二经也。"
